function detectLang() {
    let saved;
    try { saved = localStorage.getItem('gb_lang'); } catch {}
    if (saved === 'pt' || saved === 'en') return saved;
    const nav = (navigator.language || navigator.userLanguage || 'pt').toLowerCase();
    return nav.startsWith('pt') ? 'pt' : 'en';
}

function applyLang(lang) {
    const t = translations[lang];
    if (!t) return;
    document.documentElement.lang = lang === 'pt' ? 'pt-BR' : 'en';
    try { localStorage.setItem('gb_lang', lang); } catch {}
    document.querySelectorAll('[data-i18n]').forEach(el => {
        const key = el.getAttribute('data-i18n');
        if (!Object.prototype.hasOwnProperty.call(t, key)) return;
        const attr = el.getAttribute('data-i18n-attr');
        if (attr) el.setAttribute(attr, t[key]);
        else el.innerHTML = t[key];
    });
    const btn = document.getElementById('langToggle');
    if (btn) btn.innerHTML = t.nav_lang_btn;
    document.dispatchEvent(new Event('languagechange'));
}

function toggleLang() {
    const current = document.documentElement.lang === 'en' ? 'en' : 'pt';
    applyLang(current === 'pt' ? 'en' : 'pt');
}

window.__i18n = { detectLang, applyLang, toggleLang, translations };
